"use client";

import * as React from "react";
import { Lock } from "lucide-react";
import { Input } from "./input";
import { NumberRoll } from "./number-roll";
import { Select } from "./select";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";
import {
  EASE_THROW,
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * CHECKOUT: steps that stack into a receipt
 *
 *   steps     contact, shipping, delivery and payment on one
 *             surface; the step you're on is open, a rail of light
 *             runs down the numbers as you finish them
 *   stack     a finished step folds into one line under its title
 *             ("Iris Okafor, 12 Elm Street, Leeds · Change") with
 *             a check drawn in its number
 *   delivery  speeds show the day they arrive; the total on the
 *             lit summary rolls when you switch
 *   placed    Place order goes Placing order → your order number,
 *             and the steps lock
 *
 * Payment is your provider's: put its element (Stripe's Payment
 * Element, PayPal buttons, anything) in the `payment` slot, so this
 * block never sees card data. onPlaceOrder gets the order; resolve
 * with { number } to show it, throw an Error to say why not.
 * ───────────────────────────────────────────────────────── */

export interface CheckoutLine {
  id: string;
  name: string;
  /** e.g. "Sand · M". */
  detail?: string;
  quantity: number;
  /** Unit price, major units. */
  price: number;
  image?: string;
  icon?: React.ReactNode;
}

export interface CheckoutAddress {
  name: string;
  line1: string;
  line2: string;
  city: string;
  postcode: string;
  country: string;
}

export interface CheckoutDelivery {
  id: string;
  label: string;
  /** e.g. "Royal Mail Tracked". */
  detail?: string;
  price: number;
  /** Days from today it arrives: one number, or the earliest and latest. */
  days: number | [number, number];
}

export interface CheckoutOrder {
  email: string;
  address: CheckoutAddress;
  delivery: CheckoutDelivery;
  lines: CheckoutLine[];
  subtotal: number;
  discount: number;
  shipping: number;
  tax: number;
  total: number;
}

export interface CheckoutProps {
  lines: CheckoutLine[];
  deliveries: CheckoutDelivery[];
  /** Off the subtotal, major units. */
  discount?: number;
  /** Tax rate on the goods and delivery, e.g. 0.2 for 20%. */
  taxRate?: number;
  countries?: { value: string; label: string }[];
  defaultEmail?: string;
  defaultAddress?: Partial<CheckoutAddress>;
  /** Your payment provider's element, shown in the payment step. */
  payment?: React.ReactNode;
  /** Place the order; resolve with { number } to show it, throw an Error to say why not. */
  onPlaceOrder: (order: CheckoutOrder) => Promise<unknown>;
  currency?: string;
  locale?: string;
  className?: string;
}

type Step = "contact" | "shipping" | "delivery" | "payment";
const STEPS: { id: Step; title: string }[] = [
  { id: "contact", title: "Contact" },
  { id: "shipping", title: "Shipping address" },
  { id: "delivery", title: "Delivery" },
  { id: "payment", title: "Payment" },
];
const COUNTRIES = [
  { value: "US", label: "United States" },
  { value: "GB", label: "United Kingdom" },
  { value: "CA", label: "Canada" },
  { value: "DE", label: "Germany" },
  { value: "FR", label: "France" },
  { value: "AU", label: "Australia" },
  { value: "IN", label: "India" },
];
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const EASE = "cubic-bezier(0.16,1,0.3,1)";
const DAY = 86_400_000;

const subscribeNothing = () => () => {};
/** False on the server and while hydrating: text is formatted in one fixed locale until then, so the server's and the visitor's never disagree. */
const useHydrated = () =>
  React.useSyncExternalStore(
    subscribeNothing,
    () => true,
    () => false,
  );

const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const SUMMARY: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: `radial-gradient(120% 70% at 100% 0%, ${mix("var(--primary-foreground)", 22)} 0%, transparent 55%), linear-gradient(175deg, transparent 40%, ${mix("black", 24)} 100%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 36)}, inset 0 0 0 1px ${mix("var(--primary-foreground)", 12)}`,
};
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};
const INVERSE: React.CSSProperties = {
  background: "var(--primary-foreground)",
  color: "var(--primary)",
  boxShadow: `inset 0 -1px 0 ${mix("black", 8)}`,
};

function tint(seed: string): React.CSSProperties {
  let h = 0;
  for (const c of seed) h = (h * 31 + c.charCodeAt(0)) >>> 0;
  const chart = `var(--chart-${(h % 5) + 1}, var(--primary))`;
  return {
    background: mix(chart, 22, "var(--primary-foreground)"),
    color: mix(chart, 80, "black"),
  };
}

const money = (currency: string, n: number): Intl.NumberFormatOptions => ({
  style: "currency",
  currency,
  minimumFractionDigits: n % 1 ? 2 : 0,
  maximumFractionDigits: 2,
});
const round = (n: number) => Math.round(n * 100) / 100;

/** A fold that keeps its children laid out, so its height eases open and shut. */
function Fold({
  open,
  reduced,
  children,
}: {
  open: boolean;
  reduced: boolean;
  children: React.ReactNode;
}) {
  return (
    <div
      className="grid grid-cols-1"
      style={{
        gridTemplateRows: open ? "1fr" : "0fr",
        opacity: open ? 1 : 0,
        transition: reduced
          ? "opacity 160ms"
          : `grid-template-rows 440ms ${EASE}, opacity ${open ? 320 : 140}ms ${EASE} ${open ? 80 : 0}ms`,
      }}
    >
      <div className="min-h-0 overflow-clip" inert={!open || undefined}>
        {children}
      </div>
    </div>
  );
}

export function Checkout({
  lines,
  deliveries,
  discount = 0,
  taxRate = 0,
  countries = COUNTRIES,
  defaultEmail = "",
  defaultAddress,
  payment,
  onPlaceOrder,
  currency = "USD",
  locale,
  className = "",
}: CheckoutProps) {
  const reduced = useInteractionReducedMotion();
  const hydrated = useHydrated();
  const baseId = React.useId();
  const [step, setStep] = React.useState<Step>("contact");
  const [done, setDone] = React.useState<ReadonlySet<Step>>(() => new Set());
  const [email, setEmail] = React.useState(defaultEmail);
  const [address, setAddress] = React.useState<CheckoutAddress>({
    name: "",
    line1: "",
    line2: "",
    city: "",
    postcode: "",
    country: countries[0]?.value ?? "",
    ...defaultAddress,
  });
  const [deliveryId, setDeliveryId] = React.useState<string | null>(null);
  const [errors, setErrors] = React.useState<
    Partial<Record<keyof CheckoutAddress | "email", string>>
  >({});
  const [place, setPlace] = React.useState<{
    status: ActionStatus;
    number?: string;
    error?: string;
  }>({ status: "idle" });
  const [today, setToday] = React.useState<number | null>(null);
  const [said, setSaid] = React.useState("");
  const bodies = React.useRef(new Map<Step, HTMLElement>());

  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setToday(Date.now()));
    return () => cancelAnimationFrame(frame);
  }, []);

  const delivery = deliveries.find((d) => d.id === deliveryId) ?? null;
  const subtotal = round(lines.reduce((n, l) => n + l.price * l.quantity, 0));
  const off = Math.min(discount, subtotal);
  const shipping = delivery?.price ?? 0;
  const tax = round((subtotal - off + shipping) * taxRate);
  const total = round(subtotal - off + shipping + tax);
  const placed = place.status === "success";
  const busy = place.status === "pending" || placed;
  const index = STEPS.findIndex((s) => s.id === step);
  const ready =
    done.has("contact") && done.has("shipping") && done.has("delivery");

  const fmt = (n: number) => money(currency, n);
  const loc = locale ?? (hydrated ? undefined : "en-US");
  const cash = (n: number) => new Intl.NumberFormat(loc, fmt(n)).format(n);
  const arrives = (d: CheckoutDelivery) => {
    if (today === null) return "";
    const [a, b] = Array.isArray(d.days) ? d.days : [d.days, d.days];
    const day = new Intl.DateTimeFormat(loc, {
      weekday: "short",
      day: "numeric",
      month: "short",
    });
    return a === b
      ? `Arrives ${day.format(today + a * DAY)}`
      : `Arrives ${day.formatRange(today + a * DAY, today + b * DAY)}`;
  };
  const country =
    countries.find((c) => c.value === address.country)?.label ??
    address.country;
  const summaries: Record<Step, string> = {
    contact: email,
    shipping: [
      address.name,
      address.line1,
      address.line2,
      `${address.city} ${address.postcode}`.trim(),
      country,
    ]
      .filter(Boolean)
      .join(", "),
    delivery: delivery
      ? `${delivery.label} · ${delivery.price ? cash(delivery.price) : "Free"}`
      : "",
    payment: "",
  };

  const open = (s: Step) => {
    if (busy) return;
    setStep(s);
    window.setTimeout(
      () =>
        bodies.current
          .get(s)
          ?.querySelector<HTMLElement>("input,button[role=radio],button")
          ?.focus({ preventScroll: true }),
      reduced ? 0 : 320,
    );
  };

  const finish = (s: Step) => {
    if (s === "contact") {
      const problem = EMAIL.test(email.trim())
        ? undefined
        : email.trim()
          ? "That email doesn’t look right"
          : "Add your email";
      setErrors({ email: problem });
      if (problem) return;
    }
    if (s === "shipping") {
      const need: (keyof CheckoutAddress)[] = [
        "name",
        "line1",
        "city",
        "postcode",
      ];
      const problems = Object.fromEntries(
        need.filter((k) => !address[k].trim()).map((k) => [k, "Required"]),
      );
      setErrors(problems);
      if (Object.keys(problems).length) return;
    }
    if (s === "delivery" && !delivery) return;
    setDone((d) => new Set([...d, s]));
    const next =
      STEPS.find(
        (x, i) => i > STEPS.findIndex((y) => y.id === s) && !done.has(x.id),
      )?.id ?? "payment";
    setSaid(`${STEPS.find((x) => x.id === s)?.title} saved.`);
    open(next);
  };

  const placeOrder = async () => {
    if (!ready || !delivery || busy) return;
    setPlace({ status: "pending" });
    try {
      const result = await onPlaceOrder({
        email: email.trim(),
        address,
        delivery,
        lines,
        subtotal,
        discount: off,
        shipping,
        tax,
        total,
      });
      const number =
        result && typeof result === "object" && "number" in result
          ? String((result as { number: unknown }).number)
          : undefined;
      setPlace({ status: "success", number });
      setSaid(number ? `Order ${number} placed.` : "Order placed.");
    } catch (e) {
      setPlace({
        status: "error",
        error:
          e instanceof Error && e.message
            ? e.message
            : "Couldn’t place the order. Try again.",
      });
    }
  };

  const field = (
    k: keyof CheckoutAddress,
    label: string,
    autoComplete: string,
    extra?: Partial<React.ComponentProps<typeof Input>>,
  ) => (
    <Input
      label={label}
      autoComplete={autoComplete}
      value={address[k]}
      error={errors[k]}
      onValueChange={(v) => {
        setAddress((a) => ({ ...a, [k]: v }));
        if (errors[k]) setErrors((e) => ({ ...e, [k]: undefined }));
      }}
      {...extra}
    />
  );

  const next = `inline-flex h-10 cursor-pointer items-center justify-center rounded-full bg-primary px-5 text-[13.5px] font-medium text-primary-foreground hover:bg-primary/90 disabled:cursor-default disabled:opacity-45 ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`;

  return (
    <section
      aria-labelledby={`${baseId}-title`}
      className={`w-full max-w-[860px] rounded-[28px] p-2 text-card-foreground ${className}`}
      style={CARD}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 860px)" }}
      />
      <div className="@container w-full">
        <h2 id={`${baseId}-title`} className="sr-only">
          Checkout
        </h2>
        <div className="grid grid-cols-1 gap-2 @[700px]:grid-cols-[minmax(0,1fr)_320px] @[700px]:items-start">
          {/* Flat: the steps, finished ones stacked as one line each. */}
          <ol className="relative px-2 py-1" inert={placed || undefined}>
            {/* The rail of light down the numbers, as far as you've got. */}
            <span
              aria-hidden="true"
              className="absolute bottom-6 left-[19.5px] top-6 w-px bg-border"
            />
            <span
              aria-hidden="true"
              className="absolute left-[19.5px] top-6 w-px origin-top bg-primary"
              style={{
                height: "calc(100% - 48px)",
                transform: `scaleY(${Math.min(done.size, STEPS.length - 1) / (STEPS.length - 1)})`,
                transition: reduced ? "none" : `transform 620ms ${EASE}`,
              }}
            />
            {STEPS.map((s, i) => {
              const isOn = s.id === step;
              const isDone = done.has(s.id) && !isOn;
              const reachable =
                isDone ||
                i <= index ||
                STEPS.slice(0, i).every((p) => done.has(p.id));
              return (
                <li key={s.id} className="relative py-2.5 pl-9">
                  <span
                    aria-hidden="true"
                    className="absolute left-0 top-[13px] flex size-6 items-center justify-center rounded-full text-[11.5px] font-medium tabular-nums"
                    style={{
                      background: isDone ? "var(--primary)" : "var(--card)",
                      color: isDone
                        ? "var(--primary-foreground)"
                        : isOn
                          ? "var(--primary)"
                          : "var(--muted-foreground)",
                      boxShadow: isDone
                        ? "none"
                        : `inset 0 0 0 ${isOn ? 1.5 : 1}px ${isOn ? "var(--primary)" : "var(--border)"}`,
                      transition: reduced
                        ? "none"
                        : `background-color 300ms ${EASE}, box-shadow 300ms ${EASE}, color 300ms`,
                    }}
                  >
                    {isDone ? (
                      <svg viewBox="0 0 16 16" fill="none" className="size-3.5">
                        <path
                          d="M3.5 8.5 6.5 11.5 12.5 4.5"
                          stroke="currentColor"
                          strokeWidth="2.2"
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeDasharray={24}
                          className="motion-safe:animate-[ui-draw_420ms_cubic-bezier(0.16,1,0.3,1)_120ms_both]"
                        />
                      </svg>
                    ) : (
                      i + 1
                    )}
                  </span>
                  <div className="flex min-h-7 items-center justify-between gap-3">
                    <h3
                      className={`text-[14.5px] font-medium tracking-[-0.01em] ${isOn || isDone ? "text-foreground" : "text-muted-foreground"}`}
                    >
                      {s.title}
                    </h3>
                    {isDone && !placed && (
                      <button
                        type="button"
                        onClick={() => open(s.id)}
                        aria-label={`Change ${s.title.toLowerCase()}`}
                        className={`-mr-1.5 h-7 cursor-pointer rounded-full px-2.5 text-[12.5px] text-primary hover:bg-primary/10 ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
                      >
                        Change
                      </button>
                    )}
                  </div>
                  {/* The finished step, as a line of the receipt. */}
                  <Fold
                    open={isDone && Boolean(summaries[s.id])}
                    reduced={reduced}
                  >
                    <p className="truncate pb-0.5 text-[13px] text-muted-foreground">
                      {summaries[s.id]}
                    </p>
                  </Fold>
                  <Fold open={isOn} reduced={reduced}>
                    <div
                      ref={(el) => {
                        if (el) bodies.current.set(s.id, el);
                      }}
                      className="pb-1 pt-3"
                    >
                      {s.id === "contact" && (
                        <form
                          noValidate
                          className="flex flex-col gap-3 @[480px]:flex-row @[480px]:items-start"
                          onSubmit={(e) => {
                            e.preventDefault();
                            finish("contact");
                          }}
                        >
                          <Input
                            aria-label="Email"
                            type="email"
                            inputMode="email"
                            autoComplete="email"
                            placeholder="you@email.com"
                            value={email}
                            error={errors.email}
                            onValueChange={(v) => {
                              setEmail(v);
                              if (errors.email)
                                setErrors((e) => ({ ...e, email: undefined }));
                            }}
                            className="@[480px]:flex-1"
                          />
                          <button type="submit" className={next}>
                            Continue
                          </button>
                        </form>
                      )}
                      {s.id === "shipping" && (
                        <form
                          noValidate
                          className="grid grid-cols-1 gap-3 @[480px]:grid-cols-2"
                          onSubmit={(e) => {
                            e.preventDefault();
                            finish("shipping");
                          }}
                        >
                          <div className="@[480px]:col-span-2">
                            {field("name", "Full name", "name")}
                          </div>
                          <div className="@[480px]:col-span-2">
                            {field("line1", "Address", "address-line1")}
                          </div>
                          <div className="@[480px]:col-span-2">
                            {field(
                              "line2",
                              "Apartment, suite (optional)",
                              "address-line2",
                            )}
                          </div>
                          {field("city", "City", "address-level2")}
                          {field("postcode", "Postcode", "postal-code")}
                          <div className="@[480px]:col-span-2">
                            <Select
                              label="Country"
                              options={countries}
                              value={address.country}
                              onValueChange={(v) =>
                                setAddress((a) => ({ ...a, country: v }))
                              }
                            />
                          </div>
                          <div className="@[480px]:col-span-2">
                            <button type="submit" className={next}>
                              Continue
                            </button>
                          </div>
                        </form>
                      )}
                      {s.id === "delivery" && (
                        <div>
                          <div
                            role="radiogroup"
                            aria-label="Delivery speed"
                            className="overflow-clip rounded-[18px] border border-border"
                          >
                            {deliveries.map((d) => {
                              const on = d.id === deliveryId;
                              return (
                                <button
                                  key={d.id}
                                  type="button"
                                  role="radio"
                                  aria-checked={on}
                                  onClick={() => setDeliveryId(d.id)}
                                  onKeyDown={(e) => {
                                    const i2 =
                                      deliveries.indexOf(d) +
                                      (e.key === "ArrowDown" ||
                                      e.key === "ArrowRight"
                                        ? 1
                                        : e.key === "ArrowUp" ||
                                            e.key === "ArrowLeft"
                                          ? -1
                                          : 0);
                                    if (
                                      i2 === deliveries.indexOf(d) ||
                                      !deliveries[i2]
                                    )
                                      return;
                                    e.preventDefault();
                                    setDeliveryId(deliveries[i2].id);
                                    (
                                      e.currentTarget.parentElement?.children[
                                        i2
                                      ] as HTMLElement | undefined
                                    )?.focus();
                                  }}
                                  tabIndex={
                                    on || (!deliveryId && d === deliveries[0])
                                      ? 0
                                      : -1
                                  }
                                  className={`flex w-full cursor-pointer items-center gap-3 border-t border-border px-3.5 py-2.5 text-left first:border-t-0 ${on ? "bg-primary/[0.05]" : "hover:bg-accent/60"} ${INTERACTION_FOCUS} focus-visible:ring-inset focus-visible:ring-offset-0`}
                                >
                                  <span
                                    aria-hidden="true"
                                    className="flex size-[18px] shrink-0 items-center justify-center rounded-full"
                                    style={{
                                      boxShadow: `inset 0 0 0 ${on ? 5 : 1.5}px ${on ? "var(--primary)" : mix("var(--foreground)", 22, "var(--border)")}`,
                                      transition: reduced
                                        ? "none"
                                        : `box-shadow 260ms ${EASE_THROW}`,
                                    }}
                                  />
                                  <span className="min-w-0 flex-1">
                                    <span className="block text-[13.5px] font-medium text-foreground">
                                      {d.label}
                                    </span>
                                    <span className="block text-[12px] leading-snug text-muted-foreground">
                                      {arrives(d)}
                                      {d.detail ? ` · ${d.detail}` : ""}
                                    </span>
                                  </span>
                                  <span className="shrink-0 text-[13.5px] tabular-nums text-foreground">
                                    {d.price ? cash(d.price) : "Free"}
                                  </span>
                                </button>
                              );
                            })}
                          </div>
                          <button
                            type="button"
                            disabled={!delivery}
                            onClick={() => finish("delivery")}
                            className={`${next} mt-3`}
                          >
                            Continue
                          </button>
                        </div>
                      )}
                      {s.id === "payment" && (
                        <div className="text-[13px] text-muted-foreground">
                          {payment ?? <p>You’ll pay on the next page.</p>}
                          <p className="mt-2.5 inline-flex items-center gap-1.5 text-[12px]">
                            <Lock aria-hidden="true" className="size-3" />
                            {reachable && ready
                              ? "Place your order from the summary."
                              : "Finish the steps above first."}
                          </p>
                        </div>
                      )}
                    </div>
                  </Fold>
                </li>
              );
            })}
          </ol>

          {/* The one lit surface: the summary, with the order's main action. */}
          <div
            className="rounded-[22px] p-4 text-primary-foreground"
            style={SUMMARY}
          >
            <div className="flex items-baseline justify-between">
              <p className="text-[13.5px] font-medium">Order summary</p>
              <p className="text-[12px] text-primary-foreground/70">
                {lines.reduce((n, l) => n + l.quantity, 0)} items
              </p>
            </div>
            <ul className="mt-3 space-y-2.5">
              {lines.map((l) => (
                <li
                  key={l.id}
                  className="flex items-center gap-2.5 text-[13px]"
                >
                  {/* The tile clips its photo; the quantity sits on its corner, outside the clip. */}
                  <span aria-hidden="true" className="relative shrink-0">
                    <span
                      className="relative flex size-9 items-center justify-center overflow-hidden rounded-[10px] text-[12px] font-medium [&_svg]:size-[18px]"
                      style={tint(l.name)}
                    >
                      {l.icon ?? l.name.slice(0, 1)}
                      {l.image && (
                        <img
                          src={l.image}
                          alt=""
                          decoding="async"
                          className="absolute inset-0 size-full object-cover"
                        />
                      )}
                    </span>
                    {l.quantity > 1 && (
                      <span
                        className="absolute -right-1.5 -top-1.5 flex h-[18px] min-w-[18px] items-center justify-center rounded-full px-1 text-[10.5px] font-medium tabular-nums"
                        style={{
                          background: "var(--primary-foreground)",
                          color: "var(--primary)",
                          boxShadow: "0 0 0 2px var(--primary)",
                        }}
                      >
                        {l.quantity}
                      </span>
                    )}
                  </span>
                  <span className="min-w-0 flex-1">
                    <span className="block truncate font-medium">{l.name}</span>
                    {l.detail && (
                      <span className="block truncate text-[11.5px] text-primary-foreground/65">
                        {l.detail}
                      </span>
                    )}
                  </span>
                  <span className="shrink-0 tabular-nums">
                    {cash(l.price * l.quantity)}
                  </span>
                </li>
              ))}
            </ul>

            <dl
              className="mt-3.5 space-y-1.5 border-t pt-3 text-[13px]"
              style={{ borderColor: mix("var(--primary-foreground)", 18) }}
            >
              <div className="flex justify-between gap-3">
                <dt className="text-primary-foreground/70">Subtotal</dt>
                <dd className="tabular-nums">{cash(subtotal)}</dd>
              </div>
              {off > 0 && (
                <div className="flex justify-between gap-3">
                  <dt className="text-primary-foreground/70">Discount</dt>
                  <dd className="tabular-nums">−{cash(off)}</dd>
                </div>
              )}
              <div className="flex justify-between gap-3">
                <dt className="text-primary-foreground/70">Delivery</dt>
                <dd className="tabular-nums">
                  {!delivery ? (
                    <span className="text-primary-foreground/60">
                      Next step
                    </span>
                  ) : shipping ? (
                    <NumberRoll
                      value={shipping}
                      locales={locale}
                      format={fmt(shipping)}
                      duration={700}
                    />
                  ) : (
                    <TextMorph>Free</TextMorph>
                  )}
                </dd>
              </div>
              {taxRate > 0 && (
                <div className="flex justify-between gap-3">
                  <dt className="text-primary-foreground/70">Tax</dt>
                  <dd className="tabular-nums">
                    <NumberRoll
                      value={tax}
                      locales={locale}
                      format={fmt(tax)}
                      duration={700}
                    />
                  </dd>
                </div>
              )}
            </dl>
            <div
              className="mt-3 flex items-end justify-between gap-3 border-t pt-3"
              style={{ borderColor: mix("var(--primary-foreground)", 18) }}
            >
              <span className="text-[13px] text-primary-foreground/70">
                Total
              </span>
              <span className="text-[32px] font-medium leading-none tracking-[-0.04em] tabular-nums">
                <NumberRoll
                  value={total}
                  locales={locale}
                  format={fmt(total)}
                  duration={1000}
                />
              </span>
            </div>

            <StatusButton
              status={place.status}
              labels={{
                idle: "Place order",
                pending: "Placing order",
                success: place.number
                  ? `Order ${place.number}`
                  : "Order placed",
                error: "Try again",
              }}
              disabled={!ready && place.status === "idle"}
              onClick={() => void placeOrder()}
              className="mt-3.5 h-11 w-full text-[14.5px] hover:opacity-95 disabled:opacity-50"
              style={
                place.status === "error"
                  ? { background: "var(--primary-foreground)" }
                  : INVERSE
              }
            />
            <p
              role={place.error ? "alert" : undefined}
              className="mt-2 text-center text-[11.5px] text-primary-foreground/70"
            >
              {place.error ??
                (placed
                  ? `A receipt is on its way to ${email.trim()}.`
                  : ready
                    ? "You won’t be charged until you place it."
                    : "Finish the steps to place your order.")}
            </p>
          </div>
        </div>

        <span className="sr-only" role="status">
          {said}
        </span>
      </div>
    </section>
  );
}

export default Checkout;

"use client";

import * as React from "react";
import {
  Field,
  fieldSurface,
  setNativeValue,
  useFieldIds,
  useShake,
  type FieldSize,
} from "./imported-field";
import {
  EASE_OUT,
  INTERACTION_FOCUS,
  interactionIcon,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * INPUT: a one-line field
 *
 *   rest     a thin line pill; hover darkens the line
 *   focus    the line turns to the ring with a 3px halo
 *   typing   a clear button folds in once there is text and
 *            folds away when it's gone (it hands focus back)
 *   error    the line turns red, the hint gives way to the
 *            error and the field shakes once
 * ───────────────────────────────────────────────────────── */

export interface InputProps extends Omit<
  React.InputHTMLAttributes<HTMLInputElement>,
  "size"
> {
  label?: React.ReactNode;
  hint?: React.ReactNode;
  /** Shows red and replaces the hint. */
  error?: React.ReactNode;
  /** An icon or text before the value. */
  leading?: React.ReactNode;
  /** An icon, text or button after the value. */
  trailing?: React.ReactNode;
  /** A button that empties the field once it has text. */
  clearable?: boolean;
  /** 28px or 36px tall. */
  size?: FieldSize;
  /** Called with the new text on every change. */
  onValueChange?: (value: string) => void;
  ref?: React.Ref<HTMLInputElement>;
  /** Class for the outer column. */
  className?: string;
  /** Class for the input element itself. */
  inputClassName?: string;
}

function ClearIcon() {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-3.5">
      <path
        d="M4.5 4.5l7 7M11.5 4.5l-7 7"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
      />
    </svg>
  );
}

export function Input({
  label,
  hint,
  error,
  leading,
  trailing,
  clearable,
  size = "md",
  onValueChange,
  ref,
  id,
  className = "",
  inputClassName = "",
  value,
  defaultValue,
  onChange,
  disabled,
  required,
  ...props
}: InputProps) {
  const reduced = useInteractionReducedMotion();
  const ids = useFieldIds(id);
  const inner = React.useRef<HTMLInputElement>(null);
  const [text, setText] = React.useState(String(defaultValue ?? ""));
  const current = value !== undefined ? String(value) : text;
  const shakeRef = useShake<HTMLDivElement>(!!error);
  const sm = size === "sm";
  const showClear = !!clearable && current.length > 0 && !disabled;

  const setRefs = (el: HTMLInputElement | null) => {
    inner.current = el;
    if (typeof ref === "function") ref(el);
    else if (ref)
      (ref as React.RefObject<HTMLInputElement | null>).current = el;
  };

  const describedBy =
    [hint && !error ? ids.hint : null, error ? ids.error : null]
      .filter(Boolean)
      .join(" ") || undefined;

  return (
    <Field
      id={ids.id}
      label={label}
      hint={hint}
      error={error}
      required={required}
      className={className}
    >
      <div
        ref={shakeRef}
        className={`${fieldSurface({ invalid: !!error, disabled })} ${sm ? "h-7 text-[16px] sm:text-[12.5px]" : "h-9 text-[16px] sm:text-[13.5px]"}`}
      >
        {leading && (
          <span
            className={`flex shrink-0 items-center text-muted-foreground ${sm ? "pl-2.5" : "pl-3.5"} [&_svg]:size-3.5`}
          >
            {leading}
          </span>
        )}
        <input
          ref={setRefs}
          id={ids.id}
          value={value}
          defaultValue={defaultValue}
          disabled={disabled}
          required={required}
          aria-invalid={error ? true : undefined}
          aria-describedby={describedBy}
          onChange={(e) => {
            if (value === undefined) setText(e.target.value);
            onChange?.(e);
            onValueChange?.(e.target.value);
          }}
          className={`h-full min-w-0 flex-1 bg-transparent outline-none placeholder:text-muted-foreground/70 ${leading ? "pl-2" : sm ? "pl-3" : "pl-4"} ${trailing || clearable ? "pr-1" : sm ? "pr-3" : "pr-4"} ${inputClassName}`}
          {...props}
        />
        {clearable && (
          // The clear button folds its own width open, so the text never jumps.
          <span
            className="grid shrink-0"
            style={{
              gridTemplateColumns: showClear ? "1fr" : "0fr",
              transition: reduced
                ? "none"
                : `grid-template-columns 320ms ${EASE_OUT}`,
            }}
          >
            <span className="min-w-0 overflow-hidden">
              <button
                type="button"
                tabIndex={showClear ? 0 : -1}
                aria-hidden={!showClear}
                aria-label="Clear"
                onClick={() => {
                  if (!inner.current) return;
                  setNativeValue(inner.current, "");
                  inner.current.focus();
                }}
                className={`mr-1 flex items-center justify-center rounded-full text-muted-foreground cursor-pointer hover:bg-accent hover:text-foreground ${sm ? "size-5" : "size-7"} ${INTERACTION_FOCUS}`}
                style={interactionIcon(showClear, reduced)}
              >
                <ClearIcon />
              </button>
            </span>
          </span>
        )}
        {trailing && (
          <span
            className={`flex shrink-0 items-center text-muted-foreground ${sm ? "pr-1" : "pr-1.5"} [&_svg]:size-3.5`}
          >
            {trailing}
          </span>
        )}
      </div>
    </Field>
  );
}

export default Input;

"use client";

import * as React from "react";
import {
  EASE_OUT,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * FIELD: the column every text control sits in
 *
 *   label    above, with an optional aside on the right (a count)
 *   hint     under the control while all is well
 *   error    takes the hint's place: the hint folds away, the
 *            error rises in out of a blur, the control shakes once
 *
 * Shared by input, textarea, password, search and select so the
 * whole family has one surface, one focus ring and one error.
 * ───────────────────────────────────────────────────────── */

export interface FieldProps {
  id: string;
  label?: React.ReactNode;
  /** Right side of the label row, e.g. a character count. */
  aside?: React.ReactNode;
  hint?: React.ReactNode;
  error?: React.ReactNode;
  required?: boolean;
  className?: string;
  children: React.ReactNode;
}

export type FieldSize = "sm" | "md";

/** The surface of a text control: a thin line that darkens on hover and turns to the ring on focus. */
export function fieldSurface({
  invalid,
  disabled,
  round = true,
}: {
  invalid?: boolean;
  disabled?: boolean;
  round?: boolean;
}) {
  const ring = invalid
    ? "shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_55%,transparent)] focus-within:shadow-[inset_0_0_0_1px_var(--color-red-500),0_0_0_3px_color-mix(in_oklab,var(--color-red-500)_14%,transparent)]"
    : "shadow-[inset_0_0_0_1px_var(--border)] [&:not(:focus-within)]:hover:shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--foreground)_24%,var(--border))] focus-within:shadow-[inset_0_0_0_1px_var(--ring),0_0_0_3px_color-mix(in_oklab,var(--ring)_16%,transparent)]";
  return `relative flex w-full items-center bg-background text-foreground transition-[box-shadow,background-color,opacity] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] ${round ? "rounded-full" : "rounded-[14px]"} ${ring} ${
    disabled ? "pointer-events-none opacity-50" : ""
  }`;
}

/** ids for the control's label, hint and error. */
export function useFieldIds(id?: string) {
  const auto = React.useId();
  const base = id ?? auto;
  return { id: base, hint: `${base}-hint`, error: `${base}-error` };
}

/** One short shake whenever `on` turns true (an error arrives). */
export function useShake<T extends HTMLElement>(on: boolean) {
  const ref = React.useRef<T>(null);
  const reduced = useInteractionReducedMotion();
  React.useEffect(() => {
    if (!on || reduced) return;
    ref.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [on, reduced]);
  return ref;
}

/** Sets a native input's value so React's onChange still fires (clear buttons, pickers). */
export function setNativeValue(
  el: HTMLInputElement | HTMLTextAreaElement,
  value: string,
) {
  const proto =
    el instanceof HTMLTextAreaElement
      ? HTMLTextAreaElement.prototype
      : HTMLInputElement.prototype;
  Object.getOwnPropertyDescriptor(proto, "value")?.set?.call(el, value);
  el.dispatchEvent(new Event("input", { bubbles: true }));
}

/** A line under the control that folds open and closed; keeps its last words while closing. */
function Line({
  show,
  children,
  id,
  tone,
  reduced,
}: {
  show: boolean;
  children: React.ReactNode;
  id: string;
  tone: string;
  reduced: boolean;
}) {
  const [kept, setKept] = React.useState(children);
  if (show && children !== kept) setKept(children);
  return (
    <div
      className="grid"
      style={{
        gridTemplateRows: show ? "1fr" : "0fr",
        transition: reduced ? "none" : `grid-template-rows 320ms ${EASE_OUT}`,
      }}
    >
      <div className="min-h-0 overflow-hidden">
        <p
          id={id}
          className={`pt-1.5 pl-3 text-[12.5px] leading-snug ${tone}`}
          style={{
            opacity: show ? 1 : 0,
            filter: show ? "blur(0px)" : "blur(4px)",
            transform: show ? "none" : "translateY(-4px)",
            transition: reduced
              ? "none"
              : show
                ? `opacity 280ms ${EASE_OUT} 60ms, filter 280ms ${EASE_OUT} 60ms, transform 380ms ${EASE_OUT}`
                : `opacity 140ms ${EASE_OUT}, filter 140ms ${EASE_OUT}, transform 200ms ${EASE_OUT}`,
          }}
        >
          {show ? children : kept}
        </p>
      </div>
    </div>
  );
}

export function Field({
  id,
  label,
  aside,
  hint,
  error,
  required,
  className = "",
  children,
}: FieldProps) {
  const reduced = useInteractionReducedMotion();
  const ids = { hint: `${id}-hint`, error: `${id}-error` };
  return (
    <div className={`flex w-full flex-col ${className}`}>
      {(label || aside) && (
        <div className="flex items-baseline justify-between gap-3 px-3 pb-1.5">
          {label && (
            <label
              htmlFor={id}
              className="text-[13px] font-medium text-foreground"
            >
              {label}
              {required && (
                <span
                  aria-hidden="true"
                  className="ml-0.5 text-muted-foreground"
                >
                  *
                </span>
              )}
            </label>
          )}
          {aside && (
            <span className="text-[12px] tabular-nums text-muted-foreground">
              {aside}
            </span>
          )}
        </div>
      )}
      {children}
      <Line
        show={!error && !!hint}
        id={ids.hint}
        tone="text-muted-foreground"
        reduced={reduced}
      >
        {hint}
      </Line>
      <Line
        show={!!error}
        id={ids.error}
        tone="text-red-600 dark:text-red-400"
        reduced={reduced}
      >
        {error}
      </Line>
    </div>
  );
}

export default Field;

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

